// Parse da resposta do Groq
const groqResponse = $input.first().json;
const content = groqResponse.choices[0].message.content;

// Tenta parsear o JSON da resposta
let classificacao;
try {
  classificacao = JSON.parse(content);
} catch(e) {
  // Fallback se o JSON vier com markdown
  const match = content.match(/\{[\s\S]*\}/);
  classificacao = match ? JSON.parse(match[0]) : {
    tipo: 'outro',
    descricao_resumida: content,
    urgencia: 'normal',
    requer_evacuacao: false
  };
}

// Dados do solicitante
const msg = $('Somente Mensagens de Texto').first().json.message;
const chatId = msg.chat.id;
const userName = msg.from.first_name + (msg.from.last_name ? ' ' + msg.from.last_name : '');
const textoOriginal = msg.text;

// Gerar numero do chamado
const numero = 'CHM-' + Date.now().toString().slice(-6);

// Timestamp
const agora = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

return [{
  json: {
    numero_chamado: numero,
    tipo: classificacao.tipo,
    descricao: classificacao.descricao_resumida,
    urgencia: classificacao.urgencia,
    requer_evacuacao: classificacao.requer_evacuacao,
    solicitante: userName,
    chat_id: chatId,
    texto_original: textoOriginal,
    data_hora: agora,
    status: 'Aberto'
  }
}];

